class BadEqualsFields(id: String, name: String) {
    private val id = id
    private val name = name // bad

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is BadEqualsFields) return false
        return id == other.id
    }

    override fun hashCode(): Int {
        return id.hashCode()
    }
}

class GoodEqualsFields(id: String, name: String) {
    private val id = id
    private val name = name

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is GoodEqualsFields) return false
        return id == other.id && name == other.name
    }

    override fun hashCode(): Int {
        return 31 * id.hashCode() + name.hashCode()
    }
}

class PlainEqualsFields(id: String, name: String) {
    private val id = id
    private val name = name
}
